     1→// ============================================================================
     2→// FreeLang Schema 모듈 - SoA 기반 테이블 스키마
     3→// ============================================================================
     4→// 목표: SQL-like 쿼리 엔진의 기반이 되는 테이블 스키마 및 행 저장 구조
     5→// 원리:
     6→//   1. SoA(Structure of Arrays): int_cols[col_idx * MAX_ROWS + row_idx]
     7→//   2. 소프트 삭제: deleted_flags로 논리 삭제 (트랜잭션 롤백용)
     8→//   3. 타입 분리: int_cols / str_cols / bool_cols 별도 배열
     9→// 구조:
    10→//   - 상수 정의 (타입, 에러 코드, 제한값)
    11→//   - ColumnDef, TableSchema, RecordRow, Table 구조체
    12→//   - 스키마 관리 함수
    13→//   - 테이블 CRUD 함수
    14→// ============================================================================
    15→
    16→module schema {
    17→    // === 컬럼 타입 ===
    18→    const COL_TYPE_INT:   i32 = 1;
    19→    const COL_TYPE_STR:   i32 = 2;
    20→    const COL_TYPE_BOOL:  i32 = 3;
    21→
    22→    // === 제한값 ===
    23→    const MAX_COLS:  i32 = 16;
    24→    const MAX_ROWS:  i32 = 1024;
    25→
    26→    // === 에러 코드 ===
    27→    const SCHEMA_OK:          i32 = 0;
    28→    const SCHEMA_ERR_FULL:    i32 = 1;
    29→    const SCHEMA_ERR_TYPE:    i32 = 2;
    30→    const SCHEMA_ERR_DELETED: i32 = 3;
    31→    const SCHEMA_ERR_NOTFOUND: i32 = 4;
    32→
    33→    // === 데이터 구조체 ===
    34→
    35→    // 컬럼 정의
    36→    struct ColumnDef {
    37→        name:     string;
    38→        col_type: i32;
    39→        nullable: bool;
    40→    }
    41→
    42→    // 테이블 스키마 (DDL)
    43→    struct TableSchema {
    44→        name:        string;
    45→        col_defs:    [ColumnDef];
    46→        col_count:   i32;
    47→        primary_key: i32;    // 기본키 컬럼 인덱스 (0 = 첫 번째)
    48→    }
    49→
    50→    // 행 레코드 (SELECT 결과)
    51→    struct RecordRow {
    52→        row_id:     i64;
    53→        int_vals:   [i64];
    54→        str_vals:   [string];
    55→        bool_vals:  [bool];
    56→        is_deleted: bool;
    57→    }
    58→
    59→    // 테이블 (SoA 레이아웃)
    60→    struct Table {
    61→        schema:        TableSchema;
    62→        // 플래튼 SoA 배열: [col_idx * MAX_ROWS + row_idx]
    63→        int_cols:      [i64];
    64→        str_cols:      [string];
    65→        bool_cols:     [bool];
    66→        // 메타데이터
    67→        deleted_flags: [bool];
    68→        row_ids:       [i64];
    69→        row_count:     i32;
    70→        next_id:       i64;
    71→    }
    72→
    73→    // === 스키마 함수 ===
    74→
    75→    // 스키마 생성
    76→    func schema_new(name: string) -> TableSchema {
    77→        return TableSchema{
    78→            name:        name,
    79→            col_defs:    make([ColumnDef], MAX_COLS),
    80→            col_count:   0,
    81→            primary_key: 0,
    82→        };
    83→    }
    84→
    85→    // 컬럼 추가
    86→    func (s: *TableSchema) schema_add_col(name: string, col_type: i32, nullable: bool) -> bool {
    87→        if s.col_count >= MAX_COLS {
    88→            return false;
    89→        }
    90→        s.col_defs[s.col_count] = ColumnDef{
    91→            name:     name,
    92→            col_type: col_type,
    93→            nullable: nullable,
    94→        };
    95→        s.col_count = s.col_count + 1;
    96→        return true;
    97→    }
    98→
    99→    // 컬럼 이름으로 인덱스 찾기
   100→    func (s: *TableSchema) schema_find_col(name: string) -> (i32, bool) {

