     2→// FreeLang Query 모듈 - SQL-like 쿼리 실행 엔진
     3→// ============================================================================
     4→// 목표: schema.fl 기반 테이블에서 WHERE/ORDER BY/LIMIT/집계 쿼리 실행
     5→// 원리:
     6→//   1. WhereClause: 컬럼 인덱스 + 연산자 + 비교값
     7→//   2. query_execute: 전체 행 순회 → 조건 평가 → 정렬 → 페이징
     8→//   3. 집계: COUNT/SUM/MAX
     9→// 구조:
    10→//   - 상수 정의 (연산자, 집계 타입)
    11→//   - WhereClause, OrderBy, Query, QueryResult 구조체
    12→//   - 쿼리 빌더 함수 (체이닝 스타일)
    13→//   - query_execute 실행 엔진
    14→// ============================================================================
    15→
    16→module query {
    17→    // === 비교 연산자 ===
    18→    const OP_EQ:   i32 = 1;   // ==
    19→    const OP_NE:   i32 = 2;   // !=
    20→    const OP_GT:   i32 = 3;   // >
    21→    const OP_LT:   i32 = 4;   // <
    22→    const OP_GE:   i32 = 5;   // >=
    23→    const OP_LE:   i32 = 6;   // <=
    24→    const OP_LIKE: i32 = 7;   // 접두어 일치 (str_starts_with)
    25→
    26→    // === 집계 타입 ===
    27→    const AGG_NONE:  i32 = 0;
    28→    const AGG_COUNT: i32 = 1;
    29→    const AGG_SUM:   i32 = 2;
    30→    const AGG_MAX:   i32 = 3;
    31→    const AGG_MIN:   i32 = 4;
    32→
    33→    // === 제한값 ===
    34→    const MAX_WHERE: i32 = 8;
    35→    const MAX_RESULT_ROWS: i32 = 1024;
    36→
    37→    // === 에러 코드 ===
    38→    const QUERY_OK:         i32 = 0;
    39→    const QUERY_ERR_TABLE:  i32 = 10;
    40→    const QUERY_ERR_COL:    i32 = 11;
    41→    const QUERY_ERR_EMPTY:  i32 = 12;
    42→
    43→    // === 데이터 구조체 ===
    44→
    45→    struct WhereClause {
    46→        col_idx:  i32;
    47→        op:       i32;
    48→        int_val:  i64;
    49→        str_val:  string;
    50→        is_str:   bool;   // true이면 str_val 사용, false이면 int_val 사용
    51→    }
    52→
    53→    struct OrderBy {
    54→        col_idx: i32;
    55→        asc:     bool;
    56→        is_str:  bool;   // 문자열 정렬 여부
    57→    }
    58→
    59→    struct Query {
    60→        // 대상 테이블 (포인터 대신 복사 — FreeLang 제약)
    61→        table_ptr:   i32;      // 전역 테이블 인덱스 (간단화)
    62→        wheres:      [WhereClause];
    63→        where_count: i32;
    64→        order_by:    OrderBy;
    65→        has_order:   bool;
    66→        limit:       i32;
    67→        offset:      i32;
    68→        agg_type:    i32;
    69→        agg_col:     i32;
    70→    }
    71→
    72→    struct QueryResult {
    73→        // 결과 행 인덱스 (schema.Table의 row_idx)
    74→        row_indices: [i32];
    75→        row_count:   i32;
    76→        agg_value:   i64;
    77→        error_code:  i32;
    78→    }
    79→
    80→    // === 쿼리 실행 (핵심) ===
    81→    // schema.Table을 직접 받아서 처리
    82→
    83→    func query_table(t: schema.Table) -> Query {
    84→        return Query{
    85→            table_ptr:   0,
    86→            wheres:      make([WhereClause], MAX_WHERE),
