   155→    // === 행 조회 함수 ===
   156→
   157→    // 결과 집합에서 특정 행 조회
   158→    func (rs: *ResultSet) result_set_get_row(idx: i32) -> (ResultRow, i32) {
   159→        // 범위 확인
   160→        if idx < 0 || idx >= rs.row_count {
   161→            let empty_row = ResultRow{
   162→                int_vals:  make([i64], 0),
   163→                str_vals:  make([string], 0),
   164→                bool_vals: make([bool], 0),
   165→                col_count: 0,
   166→            };
   167→            return (empty_row, RESULT_ERR_EMPTY);
   168→        }
   169→
   170→        return (rs.rows[idx], RESULT_OK);
   171→    }
   172→
   173→    // 결과 집합에서 특정 행의 정수 값 조회
   174→    func (rs: *ResultSet) result_set_get_int(row_idx: i32, col_idx: i32) -> (i64, i32) {
   175→        // 행 범위 확인
   176→        if row_idx < 0 || row_idx >= rs.row_count {
   177→            return (0, RESULT_ERR_EMPTY);
   178→        }
   179→
   180→        let row = rs.rows[row_idx];
   181→
   182→        // 컬럼 범위 확인
   183→        if col_idx < 0 || col_idx >= row.col_count {
   184→            return (0, RESULT_ERR_EMPTY);
   185→        }
   186→
   187→        // int_vals 배열에서 값 추출
   188→        if col_idx < MAX_RESULT_COLS {
   189→            return (row.int_vals[col_idx], RESULT_OK);
   190→        }
   191→
   192→        return (0, RESULT_ERR_EMPTY);
   193→    }
