   195→    // 결과 집합에서 특정 행의 문자열 값 조회
   196→    func (rs: *ResultSet) result_set_get_str(row_idx: i32, col_idx: i32) -> (string, i32) {
   197→        // 행 범위 확인
   198→        if row_idx < 0 || row_idx >= rs.row_count {
   199→            return ("", RESULT_ERR_EMPTY);
   200→        }
   201→
   202→        let row = rs.rows[row_idx];
   203→
   204→        // 컬럼 범위 확인
   205→        if col_idx < 0 || col_idx >= row.col_count {
   206→            return ("", RESULT_ERR_EMPTY);
   207→        }
   208→
   209→        // str_vals 배열에서 값 추출
   210→        if col_idx < MAX_RESULT_COLS {
   211→            return (row.str_vals[col_idx], RESULT_OK);
   212→        }
   213→
   214→        return ("", RESULT_ERR_EMPTY);
   215→    }
