   268→
   269→    // i32를 문자열로 변환
   270→    @inline
   271→    func i32_to_str(n: i32) -> string {
   272→        if n == 0 { return "0"; }
   273→        if n == 1 { return "1"; }
   274→        if n == 2 { return "2"; }
   275→        if n == 3 { return "3"; }
   276→        if n == 4 { return "4"; }
   277→        if n == 5 { return "5"; }
   278→        if n == 6 { return "6"; }
   279→        if n == 7 { return "7"; }
   280→        if n == 8 { return "8"; }
   281→        if n == 9 { return "9"; }
   282→        if n < 0 { return "-" + i32_to_str(-n); }
   283→        let d = n / 10;
   284→        let r = n % 10;
   285→        return i32_to_str(d) + i32_to_str(r);
   286→    }
   287→
   288→    // i64를 문자열로 변환
   289→    @inline
   290→    func i64_to_str(n: i64) -> string {
   291→        if n == 0 { return "0"; }
   292→        if n < 0 { return "-" + i64_to_str(-n); }
   293→        return i32_to_str(i32(n));
   294→    }
   295→}
