// ============================================================================
// FreeLang Executor 모듈 - 물리 계획 실행 엔진
// ============================================================================
// 목표: PhysicalPlan 연산자를 순회 실행하여 결과 집합 생성
// 원리:
//   1. RowBuffer: 행 인덱스 배열로 추적 (메모리 효율)
//   2. Executor: 계획 + 행 버퍼 + 결과 집합 + 컨텍스트
//   3. 메인 루프: root_op_idx부터 시작 → 연산자별 실행 → next_op 순회
//   4. 연산자 유형: TABLE_SCAN, FILTER, SORT, LIMIT, AGGREGATE
// 구조:
//   - 상수 정의 (에러 코드 130-133, 제한값)
//   - RowBuffer, Executor 구조체
//   - 초기화 및 실행 함수 (12개 공개 API)
//   - 연산자별 헬퍼 함수
// ============================================================================

module executor {
    // === 에러 코드 ===
    const EXEC_OK:               i32 = 0;
    const EXEC_ERR_NOT_FOUND:    i32 = 130;
    const EXEC_ERR_INVALID_OP:   i32 = 131;
    const EXEC_ERR_INVALID_PLAN: i32 = 132;
    const EXEC_ERR_FULL:         i32 = 133;

    // === 제한값 ===
    const MAX_ROW_BUFFER: i32 = 1024;

    // === 데이터 구조체 ===

    // 행 버퍼 (행 인덱스 배열)
    struct RowBuffer {
        row_indices: [i32];
        count:       i32;
    }

    // 실행 엔진
    struct Executor {
        plan:       physical_plan.PhysicalPlan;
        row_buf:    RowBuffer;
        result:     result_set.ResultSet;
        qctx:       query_context.QueryContext;
        has_error:  bool;
        error_code: i32;
    }

    // === 초기화 함수 ===

    // 새로운 Executor 생성 및 초기화
    func executor_new() -> Executor {
        let ex = Executor{
            plan:       physical_plan.physical_plan_new(),
            row_buf:    RowBuffer{
                row_indices: make([i32], MAX_ROW_BUFFER),
                count:       0,
            },
            result:     result_set.result_set_new(16),
            qctx:       query_context.query_context_new(0),
            has_error:  false,
            error_code: EXEC_OK,
        };
        return ex;
    }

    // Executor 초기화 (계획 및 테이블 설정)
    func executor_init(ex: *Executor, pp: physical_plan.PhysicalPlan, t: schema.Table) -> i32 {
        // 물리 계획 검증
        if !physical_plan.physical_plan_validate(&pp) {
            ex.has_error = true;
            ex.error_code = EXEC_ERR_INVALID_PLAN;
            return EXEC_ERR_INVALID_PLAN;
        }

        // 계획 설정
        ex.plan = pp;

        // 행 버퍼 초기화
        ex.row_buf.count = 0;

        // 결과 집합 초기화
        let col_count = t.schema.col_count;
        ex.result = result_set.result_set_new(col_count);

        // 컨텍스트 초기화
        ex.qctx = query_context.query_context_new(1);

        ex.has_error = false;
        ex.error_code = EXEC_OK;

        return EXEC_OK;
    }

    // === 메인 실행 루프 ===

    // 물리 계획 실행 (메인 엔진)
    func executor_execute(ex: *Executor, t: schema.Table) -> i32 {
        // 계획 검증
        if ex.plan.root_op_idx < 0 {
            ex.has_error = true;
            ex.error_code = EXEC_ERR_INVALID_PLAN;
            return EXEC_ERR_INVALID_PLAN;
        }

        // 행 버퍼 초기화
        ex.row_buf.count = 0;

        // 결과 집합 초기화
        let res = ex.result.result_set_clear();
        if res != result_set.RESULT_OK {
            ex.has_error = true;
            ex.error_code = EXEC_ERR_FULL;
            return EXEC_ERR_FULL;
        }

        // 루트 연산자부터 시작
        let op_idx = ex.plan.root_op_idx;
        let visited = 0;

        // 파이프라인 순회 (최대 32개 연산자)
        for visited = 0; visited < 32 && op_idx >= 0; visited = visited + 1 {
            if op_idx >= physical_plan.MAX_OPS {
                ex.has_error = true;
                ex.error_code = EXEC_ERR_INVALID_OP;
                return EXEC_ERR_INVALID_OP;
            }

            let op = ex.plan.ops[op_idx];

            // 연산자 타입별 실행
            if op.op_type == physical_plan.PHYS_PLAN_TABLE_SCAN {
                let err = executor_exec_table_scan(ex, t);
                if err != EXEC_OK {
                    ex.has_error = true;
                    ex.error_code = err;
                    return err;
                }
            } else if op.op_type == physical_plan.PHYS_PLAN_FILTER {
                let err = executor_exec_filter(ex, t, op.col_idx);
                if err != EXEC_OK {
                    ex.has_error = true;
                    ex.error_code = err;
                    return err;
                }
            } else if op.op_type == physical_plan.PHYS_PLAN_SORT {
                let err = executor_exec_sort(ex, t, op.col_idx);
                if err != EXEC_OK {
                    ex.has_error = true;
                    ex.error_code = err;
                    return err;
                }
            } else if op.op_type == physical_plan.PHYS_PLAN_LIMIT {
                let err = executor_exec_limit(ex, op.limit_count);
                if err != EXEC_OK {
                    ex.has_error = true;
                    ex.error_code = err;
                    return err;
                }
            } else if op.op_type == physical_plan.PHYS_PLAN_AGGREGATE {
                let err = executor_exec_aggregate(ex, t, op.agg_type, op.col_idx);
                if err != EXEC_OK {
                    ex.has_error = true;
                    ex.error_code = err;
                    return err;
                }
            }

            // 다음 연산자로 이동
            op_idx = op.next_op;
        }

        // 행 버퍼 → 결과 집합 복사
        let err = executor_finalize_result(ex, t);
        if err != EXEC_OK {
            ex.has_error = true;
            ex.error_code = err;
            return err;
        }

        ex.has_error = false;
        ex.error_code = EXEC_OK;
        return EXEC_OK;
    }

    // === 연산자 실행 함수 ===

    // TABLE_SCAN: 모든 활성 행을 행 버퍼에 추가
    func executor_exec_table_scan(ex: *Executor, t: schema.Table) -> i32 {
        let row_idx = 0;

        // 모든 행 순회
        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
            // 소프트 삭제 확인
            if !t.deleted_flags[row_idx] {
                // 행 버퍼 용량 확인
                if ex.row_buf.count >= MAX_ROW_BUFFER {
                    return EXEC_ERR_FULL;
                }

                // 행 인덱스 추가
                ex.row_buf.row_indices[ex.row_buf.count] = row_idx;
                ex.row_buf.count = ex.row_buf.count + 1;
            }
        }

        return EXEC_OK;
    }

    // FILTER: 조건(col_idx > 0)을 만족하는 행만 유지
    func executor_exec_filter(ex: *Executor, t: schema.Table, col_idx: i32) -> i32 {
        if col_idx < 0 || col_idx >= t.schema.col_count {
            return EXEC_ERR_INVALID_OP;
        }

        let new_count = 0;
        let i = 0;

        // 각 행에 대해 필터 조건 적용
        for i = 0; i < ex.row_buf.count; i = i + 1 {
            let row_idx = ex.row_buf.row_indices[i];

            // 컬럼 값 추출 (정수 컬럼으로 가정)
            let col_val = t.int_cols[col_idx * schema.MAX_ROWS + row_idx];

            // > 0 조건 필터
            if col_val > 0 {
                ex.row_buf.row_indices[new_count] = row_idx;
                new_count = new_count + 1;
            }
        }

        ex.row_buf.count = new_count;
        return EXEC_OK;
    }

    // SORT: 삽입 정렬(insertion sort)로 행 정렬
    func executor_exec_sort(ex: *Executor, t: schema.Table, sort_col: i32) -> i32 {
        if sort_col < 0 || sort_col >= t.schema.col_count {
            return EXEC_ERR_INVALID_OP;
        }

        let i = 1;

        // 삽입 정렬
        for i = 1; i < ex.row_buf.count; i = i + 1 {
            let key_idx = ex.row_buf.row_indices[i];
            let key_val = t.int_cols[sort_col * schema.MAX_ROWS + key_idx];

            let j = i - 1;

            // 삽입 위치 찾기
            for j = i - 1; j >= 0; j = j - 1 {
                let curr_row_idx = ex.row_buf.row_indices[j];
                let curr_val = t.int_cols[sort_col * schema.MAX_ROWS + curr_row_idx];

                if curr_val <= key_val {
                    break;
                }

                // 한 칸씩 뒤로 이동
                ex.row_buf.row_indices[j + 1] = ex.row_buf.row_indices[j];
            }

            // 올바른 위치에 삽입
            ex.row_buf.row_indices[j + 1] = key_idx;
        }

        return EXEC_OK;
    }

    // LIMIT: 행 개수 제한
    func executor_exec_limit(ex: *Executor, limit_count: i32) -> i32 {
        if limit_count <= 0 {
            return EXEC_OK;
        }

        if ex.row_buf.count > limit_count {
            ex.row_buf.count = limit_count;
        }

        return EXEC_OK;
    }

    // AGGREGATE: 집계 함수 실행 (COUNT/SUM/MAX/MIN)
    func executor_exec_aggregate(ex: *Executor, t: schema.Table, agg_type: i32, agg_col: i32) -> i32 {
        if agg_col < 0 || agg_col >= t.schema.col_count {
            return EXEC_ERR_INVALID_OP;
        }

        let agg_val: i64 = 0;
        let i = 0;

        if agg_type == physical_plan.PHYS_AGG_COUNT {
            agg_val = i64(ex.row_buf.count);
        } else if agg_type == physical_plan.PHYS_AGG_SUM {
            agg_val = 0;
            for i = 0; i < ex.row_buf.count; i = i + 1 {
                let row_idx = ex.row_buf.row_indices[i];
                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
                agg_val = agg_val + col_val;
            }
        } else if agg_type == physical_plan.PHYS_AGG_MAX {
            agg_val = -9223372036854775808;
            for i = 0; i < ex.row_buf.count; i = i + 1 {
                let row_idx = ex.row_buf.row_indices[i];
                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
                if col_val > agg_val {
                    agg_val = col_val;
                }
            }
        } else if agg_type == physical_plan.PHYS_AGG_MIN {
            agg_val = 9223372036854775807;
            for i = 0; i < ex.row_buf.count; i = i + 1 {
                let row_idx = ex.row_buf.row_indices[i];
                let col_val = t.int_cols[agg_col * schema.MAX_ROWS + row_idx];
                if col_val < agg_val {
                    agg_val = col_val;
                }
            }
        }

        // 결과를 단일 행으로 저장
        ex.row_buf.count = 1;
        ex.row_buf.row_indices[0] = 0;

        let new_row = result_set.ResultRow{
            int_vals:  make([i64],    result_set.MAX_RESULT_COLS),
            str_vals:  make([string], result_set.MAX_RESULT_COLS),
            bool_vals: make([bool],   result_set.MAX_RESULT_COLS),
            col_count: 1,
        };

        new_row.int_vals[0] = agg_val;
        ex.result.rows[0] = new_row;
        ex.result.row_count = 1;

        return EXEC_OK;
    }

    // === 결과 수집 함수 ===

    // 행 버퍼를 결과 집합에 복사
    func executor_finalize_result(ex: *Executor, t: schema.Table) -> i32 {
        let i = 0;

        // 각 행 인덱스를 결과 집합에 추가
        for i = 0; i < ex.row_buf.count; i = i + 1 {
            let row_idx = ex.row_buf.row_indices[i];

            let err = ex.result.result_set_add_row_from_schema(t, row_idx);
            if err != result_set.RESULT_OK {
                return EXEC_ERR_FULL;
            }
        }

        return EXEC_OK;
    }

    // === 조회 함수 ===

    // 결과 집합 반환
    func executor_get_result(ex: *Executor) -> result_set.ResultSet {
        return ex.result;
    }

    // 결과 행 개수 반환
    func executor_get_row_count(ex: *Executor) -> i32 {
        return ex.result.row_count;
    }

    // === 통계 및 디버그 함수 ===

    // Executor 상태 문자열 반환
    func executor_stats(ex: *Executor) -> string {
        let stat = "Executor {row_buf.count: ";
        stat = stat + i32_to_str(ex.row_buf.count);
        stat = stat + ", result.row_count: ";
        stat = stat + i32_to_str(ex.result.row_count);
        stat = stat + ", error_code: ";
        stat = stat + i32_to_str(ex.error_code);
        stat = stat + "}";
        return stat;
    }

    // === 헬퍼 함수 ===

    // i32를 문자열로 변환
    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }
}
